    await expect(page.getByText("Draft", { exact: true })).toBeVisible();
    await page.getByRole("button", { name: "Edit course", exact: true }).click();
    await expect(page.getByLabel("Course title", { exact: true })).toHaveValue("Alpha Course");
    await expect(page.getByLabel("Stage 1 title", { exact: true })).toHaveValue("Stage One");
    await expect(page.getByLabel("Stage 1 objective 1", { exact: true })).toHaveValue("Obj A");
    await expect(page.getByLabel("Stage 1 objective 2", { exact: true })).toHaveValue("Obj B");
    await expect(page.getByLabel("Stage 2 title", { exact: true })).toHaveValue("Stage Two");
    await expect(page.getByLabel("Stage 2 objective 1", { exact: true })).toHaveValue("Obj C");
    { const order=await page.evaluate(()=>Array.from(document.querySelectorAll("input, textarea")).map(el=>el.getAttribute("aria-label")||el.id)); const indices=["Course title","Stage 1 title","Stage 1 objective 1","Stage 1 objective 2","Stage 2 title","Stage 2 objective 1"].map(name=>order.indexOf(name)); for(let i=0;i<indices.length;i++){ expect(indices[i]).toBeGreaterThanOrEqual(0); if(i>0) expect(indices[i-1]).toBeLessThan(indices[i]); } }
});

